    for (const [hx, hy] of [[3, 4], [24, 4], [3, 17], [24, 17]]) { rect(sq, hx, hy, hx + 7, hy + 3, 14); rect(sq, hx, hy, hx + 7, hy, 16); set(sq, hx + 3, hy + 3, 17); set(sq, hx + 1, hy + 2, 18); set(sq, hx + 5, hy + 2, 18); }
