    credits: { label: 'Credits', family: 'story', group: 'Screens & story', icon: '\u{1F39E}', about: 'Scrolling credits.' },
    transition: { label: 'Transition', family: 'story', group: 'Screens & story', icon: '\u{1F6AA}', about: 'Fade, wipe, door, vehicle or portal between two sections (get in the car, walk through a door).' },
    level: { label: 'Platformer level', family: 'platformer', group: 'Platformer', icon: '\u{1F3C3}', about: 'A level from the Level tab (side-scrolling).' },
