    rpg: { label: 'RPG world', family: 'rpg', group: 'Open world & adventure', icon: '\u{1F9D9}', about: 'The World tab maps as an RPG.' },
    fps: { label: 'First-person maze', family: 'fps3d', group: 'Action & shooters', icon: '\u{1F52B}', about: 'A maze level for the N64 / PlayStation first-person ROM.' },
