    world: { label: 'Open-world map', family: 'world', group: 'Open world & adventure', icon: '\u{1F5FA}', about: 'A World-tab map played top-down (PC / Xbox / DS).' },
    puzzle: { label: 'Puzzle game', family: 'puzzle', group: 'Minigames & arcade', icon: '\u{1F9E9}', about: 'Match-3 or bracelet pattern puzzle (PC / DS).' },
